package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader *bufio.Reader
var writer *bufio.Writer

func isSpaceChar(c int) bool {
	return !(c >= 33 && c <= 126)
}

func readByte() int {
	b, err := reader.ReadByte()
	if err != nil {
		return -1
	}
	return int(b)
}

func skip() int {
	b := readByte()
	for b != -1 && isSpaceChar(b) {
		b = readByte()
	}
	return b
}

func ns() string {
	b := skip()
	sb := make([]byte, 0)
	for b != -1 && !isSpaceChar(b) {
		sb = append(sb, byte(b))
		b = readByte()
	}
	return string(sb)
}

func ni() int {
	num := 0
	b := readByte()
	minus := false
	for b != -1 && !((b >= '0' && b <= '9') || b == '-') {
		b = readByte()
	}
	if b == '-' {
		minus = true
		b = readByte()
	}
	for {
		if b >= '0' && b <= '9' {
			num = num*10 + (b - '0')
		} else {
			if minus {
				return -num
			}
			return num
		}
		b = readByte()
	}
}

func solve() {
	_ = ni()
	s := ns()
	r := 0

	for i := 1; i < len(s); i++ {
		if s[i] == s[i-1] {
			r++
		}
	}

	writer.WriteString(strconv.Itoa(r))
	writer.WriteString("\n")
}

func main() {
	reader = bufio.NewReader(os.Stdin)
	writer = bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	solve()
}
